CREATE TABLE IF NOT EXISTS branches17(id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE, address TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS copies17(id INTEGER PRIMARY KEY,book_id INTEGER NOT NULL REFERENCES books(id),barcode TEXT NOT NULL UNIQUE,branch_id INTEGER REFERENCES branches17(id),location TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'Available' CHECK(status IN ('Available','Borrowed','Lost','Damaged','Maintenance')));
CREATE TABLE IF NOT EXISTS reservations17(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),book_id INTEGER NOT NULL REFERENCES books(id),status TEXT NOT NULL DEFAULT 'Waiting',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX IF NOT EXISTS reservation17_live ON reservations17(user_id,book_id) WHERE status='Waiting';
CREATE TABLE IF NOT EXISTS fines17(id INTEGER PRIMARY KEY,loan_id INTEGER NOT NULL REFERENCES lending_loans(id),amount_paise INTEGER NOT NULL CHECK(amount_paise>=0),paid_paise INTEGER NOT NULL DEFAULT 0 CHECK(paid_paise>=0),reason TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS fine_payments17(id INTEGER PRIMARY KEY,fine_id INTEGER NOT NULL REFERENCES fines17(id),amount_paise INTEGER NOT NULL,reference TEXT NOT NULL,admin_id INTEGER NOT NULL REFERENCES admin_users(id),created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS notifications17(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),title TEXT NOT NULL,body TEXT NOT NULL DEFAULT '',url TEXT NOT NULL DEFAULT '/members/dashboard/',dedupe TEXT UNIQUE,is_read INTEGER NOT NULL DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS conversations17(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),assigned_id INTEGER REFERENCES admin_users(id),subject TEXT NOT NULL,category TEXT NOT NULL DEFAULT 'Support',status TEXT NOT NULL DEFAULT 'Open' CHECK(status IN ('Open','Escalated','Closed')),created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS messages17(id INTEGER PRIMARY KEY,conversation_id INTEGER NOT NULL REFERENCES conversations17(id),sender_user INTEGER REFERENCES users(id),sender_admin INTEGER REFERENCES admin_users(id),body TEXT NOT NULL,file_key TEXT NOT NULL DEFAULT '',file_name TEXT NOT NULL DEFAULT '',read_at TEXT NOT NULL DEFAULT '',created_at TEXT DEFAULT CURRENT_TIMESTAMP,CHECK((sender_user IS NULL)!=(sender_admin IS NULL)));
CREATE TABLE IF NOT EXISTS presence17(conversation_id INTEGER NOT NULL REFERENCES conversations17(id),actor TEXT NOT NULL,last_seen INTEGER NOT NULL,typing_until INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(conversation_id,actor));
CREATE TABLE IF NOT EXISTS auth_tokens17(token_hash TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),purpose TEXT NOT NULL,expires_at INTEGER NOT NULL,used INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS mail_queue17(id INTEGER PRIMARY KEY,recipient TEXT NOT NULL,subject TEXT NOT NULL,body TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'Pending',attempts INTEGER NOT NULL DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS rate_limits17(bucket TEXT PRIMARY KEY,count INTEGER NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS payments17(id INTEGER PRIMARY KEY,subscription_id INTEGER NOT NULL REFERENCES lending_subscriptions(id),order_id TEXT UNIQUE,payment_id TEXT UNIQUE,amount_paise INTEGER NOT NULL,currency TEXT NOT NULL DEFAULT 'INR',status TEXT NOT NULL DEFAULT 'Pending',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS coupons17(id INTEGER PRIMARY KEY,code TEXT NOT NULL UNIQUE COLLATE NOCASE,percent INTEGER NOT NULL CHECK(percent BETWEEN 1 AND 100),max_uses INTEGER NOT NULL DEFAULT 0,expires_on TEXT NOT NULL DEFAULT '',is_active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS coupon_uses17(coupon_id INTEGER NOT NULL REFERENCES coupons17(id),subscription_id INTEGER NOT NULL UNIQUE REFERENCES lending_subscriptions(id),PRIMARY KEY(coupon_id,subscription_id));
CREATE INDEX IF NOT EXISTS copy17_book ON copies17(book_id,status);
CREATE INDEX IF NOT EXISTS notification17_user ON notifications17(user_id,is_read);
CREATE INDEX IF NOT EXISTS message17_conversation ON messages17(conversation_id,id);

CREATE TABLE IF NOT EXISTS conversation_members17(conversation_id INTEGER NOT NULL REFERENCES conversations17(id),user_id INTEGER NOT NULL REFERENCES users(id),PRIMARY KEY(conversation_id,user_id));
